// Cuba's light badge, rendered as plain markup.
//
// Not reactstrap's <Badge color='light-success'>: that emits `bg-light-success`,
// and Cuba's class is `badge-light-success` (generated by the @each loop in
// pages/_dashboard_default.scss). Worse, Bootstrap 5's `bg-*` utilities carry
// !important, so even adding the Cuba class alongside loses the background.
// A span with Cuba's own two classes is what the template actually uses.
//
// `tone` is the class suffix exactly as Cuba spells it, so the call site reads
// the same as the stylesheet: tone='light-success' -> badge-light-success.

import type { ReactNode } from 'react';

export type BadgeTone =
  | 'light-primary'
  | 'light-secondary'
  | 'light-success'
  | 'light-danger'
  | 'light-info'
  | 'light-warning'
  | 'light-dark';

const StatusBadge = ({
  tone,
  children,
}: {
  tone: BadgeTone;
  children: ReactNode;
}) => <span className={`badge badge-${tone}`}>{children}</span>;

export default StatusBadge;
